# Prints Yes for an uppercase letter followed by lowercase ones
S = input()
C = S[0]
D = S[1:]
ans = True
if len(S) == 1:
    ans = C.isupper()
else:
    ans = C.isupper() and D.islower()
if ans:
    print("Yes")
else:
    print("No")

